create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,nickname text not null default 'Listener',username text not null unique,bio text default '',avatar_url text,banner_url text,created_at timestamptz default now());
create table if not exists public.tracks(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,title text not null,description text default '',audio_url text not null,cover_url text,source text default 'upload',source_id text,created_at timestamptz default now());
create table if not exists public.likes(id uuid primary key default gen_random_uuid(),user_id uuid references public.profiles(id) on delete cascade,track_id uuid references public.tracks(id) on delete cascade,created_at timestamptz default now(),unique(user_id,track_id));
create table if not exists public.reposts(id uuid primary key default gen_random_uuid(),user_id uuid references public.profiles(id) on delete cascade,track_id uuid references public.tracks(id) on delete cascade,created_at timestamptz default now(),unique(user_id,track_id));
create table if not exists public.comments(id uuid primary key default gen_random_uuid(),user_id uuid references public.profiles(id) on delete cascade,track_id uuid references public.tracks(id) on delete cascade,body text not null check(char_length(body) between 1 and 500),created_at timestamptz default now());
alter table public.profiles enable row level security;alter table public.tracks enable row level security;alter table public.likes enable row level security;alter table public.reposts enable row level security;alter table public.comments enable row level security;
create policy "profiles read" on public.profiles for select using(true);create policy "profile insert own" on public.profiles for insert with check(auth.uid()=id);create policy "profile update own" on public.profiles for update using(auth.uid()=id) with check(auth.uid()=id);
create policy "tracks read" on public.tracks for select using(true);create policy "tracks insert own" on public.tracks for insert with check(auth.uid()=user_id);create policy "tracks update own" on public.tracks for update using(auth.uid()=user_id);create policy "tracks delete own" on public.tracks for delete using(auth.uid()=user_id);
create policy "likes read" on public.likes for select using(true);create policy "likes insert own" on public.likes for insert with check(auth.uid()=user_id);create policy "likes delete own" on public.likes for delete using(auth.uid()=user_id);
create policy "reposts read" on public.reposts for select using(true);create policy "reposts insert own" on public.reposts for insert with check(auth.uid()=user_id);create policy "reposts delete own" on public.reposts for delete using(auth.uid()=user_id);
create policy "comments read" on public.comments for select using(true);create policy "comments insert own" on public.comments for insert with check(auth.uid()=user_id);create policy "comments delete own" on public.comments for delete using(auth.uid()=user_id);
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('sonora-media','sonora-media',true,52428800,array['audio/mpeg','audio/mp4','audio/aac','audio/wav','audio/ogg','audio/flac','image/jpeg','image/png','image/webp']) on conflict(id) do nothing;
create policy "public media read" on storage.objects for select using(bucket_id='sonora-media');create policy "upload own media" on storage.objects for insert to authenticated with check(bucket_id='sonora-media' and (storage.foldername(name))[1]=auth.uid()::text);create policy "delete own media" on storage.objects for delete to authenticated using(bucket_id='sonora-media' and (storage.foldername(name))[1]=auth.uid()::text);